def subtract(a, b):
    def merge_intervals(intervals):
        """Merge overlapping/touching intervals and remove empty ones"""
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()

        merged = [valid[0]]
        for start, end in valid[1:]:
            last_start, last_end = merged[-1]
            if start <= last_end:
                # Overlapping or touching, merge
                merged[-1] = [last_start, max(last_end, end)]
            else:
                # Disjoint, add new interval
                merged.append([start, end])

        return merged

    # Merge both input lists
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        # Start with the full interval from a
        current_intervals = [[a_start, a_end]]

        # Subtract each interval in b
        for b_start, b_end in b_merged:
            new_intervals = []
            for curr_start, curr_end in current_intervals:
                # Check if b interval overlaps with current interval
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap, keep current interval
                    new_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap, split current interval
                    if curr_start < b_start:
                        new_intervals.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_intervals.append([b_end, curr_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    return result

